    28	/* Scan file for objects and reconstruct xref table */
    29	
    30	struct entry
    31	{
    32	        int num;
    33	        int gen;
    34	        int64_t ofs;
    35	        int64_t stm_ofs;
    36	        int64_t stm_len;
    37	};
