    39	static void add_root(fz_context *ctx, pdf_obj *obj, pdf_obj ***roots, int *num_roots, int *max_roots)
    40	{
    41	        if (*num_roots == *max_roots)
    42	        {
    43	                int new_max_roots = *max_roots * 2;
    44	                if (new_max_roots == 0)
    45	                        new_max_roots = 4;
    46	                *roots = fz_realloc_array(ctx, *roots, new_max_roots, pdf_obj*);
    47	                *max_roots = new_max_roots;
    48	        }
    49	        (*roots)[(*num_roots)++] = pdf_keep_obj(ctx, obj);
    50	}
    51	
    52	int
    53	pdf_repair_obj(fz_context *ctx, pdf_document *doc, pdf_lexbuf *buf, int64_t *stmofsp, int64_t *stmlenp, pdf_obj **encrypt, pdf_obj **id, pdf_obj **page, int64_t *tmpofs, pdf_obj **root)
    54	{
    55	        fz_stream *file = doc->file;
    56	        pdf_token tok;
    57	        int64_t stm_len;
    58	        int64_t local_ofs;
    59	
    60	        if (tmpofs == NULL)
    61	                tmpofs = &local_ofs;
    62	        if (stmofsp == NULL)
    63	                stmofsp = &local_ofs;
    64	
    65	        *stmofsp = 0;
    66	        if (stmlenp)
    67	                *stmlenp = -1;
    68	
    69	        stm_len = 0;
    70	
    71	        *tmpofs = fz_tell(ctx, file);
    72	        if (*tmpofs < 0)
    73	                fz_throw(ctx, FZ_ERROR_GENERIC, "cannot tell in file");
    74	
    75	        /* On entry to this function, we know that we've just seen
    76	         * '<int> <int> obj'. We expect the next thing we see to be a
    77	         * pdf object. Regardless of the type of thing we meet next
    78	         * we only need to fully parse it if it is a dictionary. */
    79	        tok = pdf_lex(ctx, file, buf);
    80	
    81	        /* Don't let a truncated object at EOF overwrite a good one */
    82	        if (tok == PDF_TOK_EOF)
    83	                fz_throw(ctx, FZ_ERROR_SYNTAX, "truncated object");
    84	
    85	        if (tok == PDF_TOK_OPEN_DICT)
    86	        {
    87	                pdf_obj *obj, *dict = NULL;
    88	
    89	                fz_try(ctx)
    90	                {
    91	                        dict = pdf_parse_dict(ctx, doc, file, buf);
    92	                }
    93	                fz_catch(ctx)
    94	                {
    95	                        fz_rethrow_if(ctx, FZ_ERROR_TRYLATER);
    96	                        /* Don't let a broken object at EOF overwrite a good one */
    97	                        if (file->eof)
    98	                                fz_rethrow(ctx);
    99	                        /* Silently swallow the error */
   100	                        dict = pdf_new_dict(ctx, NULL, 2);
   101	                }
   102	
   103	                /* We must be careful not to try to resolve any indirections
   104	                 * here. We have just read dict, so we know it to be a non
   105	                 * indirected dictionary. Before we look at any values that
   106	                 * we get back from looking up in it, we need to check they
   107	                 * aren't indirected. */
   108	
   109	                if (encrypt || id || root)
   110	                {
   111	                        obj = pdf_dict_get(ctx, dict, PDF_NAME(Type));
   112	                        if (!pdf_is_indirect(ctx, obj) && pdf_name_eq(ctx, obj, PDF_NAME(XRef)))
   113	                        {
   114	                                if (encrypt)
   115	                                {
   116	                                        obj = pdf_dict_get(ctx, dict, PDF_NAME(Encrypt));
   117	                                        if (obj)
   118	                                        {
   119	                                                pdf_drop_obj(ctx, *encrypt);
   120	                                                *encrypt = pdf_keep_obj(ctx, obj);
   121	                                        }
   122	                                }
   123	
   124	                                if (id)
   125	                                {
   126	                                        obj = pdf_dict_get(ctx, dict, PDF_NAME(ID));
   127	                                        if (obj)
   128	                                        {
   129	                                                pdf_drop_obj(ctx, *id);
   130	                                                *id = pdf_keep_obj(ctx, obj);
   131	                                        }
   132	                                }
   133	
   134	                                if (root)
   135	                                        *root = pdf_keep_obj(ctx, pdf_dict_get(ctx, dict, PDF_NAME(Root)));
   136	                        }
   137	                }
   138	
   139	                obj = pdf_dict_get(ctx, dict, PDF_NAME(Length));
   140	                if (!pdf_is_indirect(ctx, obj) && pdf_is_int(ctx, obj))
   141	                        stm_len = pdf_to_int64(ctx, obj);
   142	
   143	                if (doc->file_reading_linearly && page)
   144	                {
   145	                        obj = pdf_dict_get(ctx, dict, PDF_NAME(Type));
   146	                        if (!pdf_is_indirect(ctx, obj) && pdf_name_eq(ctx, obj, PDF_NAME(Page)))
   147	                        {
   148	                                pdf_drop_obj(ctx, *page);
   149	                                *page = pdf_keep_obj(ctx, dict);
   150	                        }
   151	                }
   152	
   153	                pdf_drop_obj(ctx, dict);
   154	        }
   155	
   156	        while ( tok != PDF_TOK_STREAM &&
   157	                tok != PDF_TOK_ENDOBJ &&
   158	                tok != PDF_TOK_ERROR &&
   159	                tok != PDF_TOK_EOF &&
   160	                tok != PDF_TOK_INT )
   161	        {
   162	                *tmpofs = fz_tell(ctx, file);
   163	                if (*tmpofs < 0)
   164	                        fz_throw(ctx, FZ_ERROR_GENERIC, "cannot tell in file");
   165	                tok = pdf_lex(ctx, file, buf);
   166	        }
   167	
   168	        if (tok == PDF_TOK_STREAM)
   169	        {
   170	                int c = fz_read_byte(ctx, file);
   171	                if (c == '\r') {
   172	                        c = fz_peek_byte(ctx, file);
   173	                        if (c == '\n')
   174	                                fz_read_byte(ctx, file);
   175	                }
   176	
   177	                *stmofsp = fz_tell(ctx, file);
   178	                if (*stmofsp < 0)
   179	                        fz_throw(ctx, FZ_ERROR_GENERIC, "cannot seek in file");
